import { useEffect, useState } from 'react';
import {
  fetchWatchedFolders,
  createWatchedFolder,
  deleteWatchedFolder,
  pickFolderPath, // ✅ 추가: GET /settings/folders/pick
} from '../api/SettingApi';

export function useWatchedFolders() {
  const [folders, setFolders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = async () => {
    try {
      setLoading(true);
      setError(null);

      const data = await fetchWatchedFolders();
      const list = Array.isArray(data) ? data : (data?.items ?? []);

      setFolders(
        list.map((it) => ({
          id: it.id ?? it.folderId ?? it.path,
          name: it.name ?? it.folderName ?? '폴더',
          path: it.path,
        }))
      );
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
  }, []);

  /**
   * ✅ 폴더 선택 다이얼로그로 경로를 받아서 추가
   * - 백엔드: GET /settings/folders/pick -> {path} 또는 204(No Content)
   */
  const pickAndAddFolder = async () => {
    try {
      const res = await pickFolderPath(); // 204면 null
      if (!res || !res.path) return; // 사용자가 취소한 경우

      const path = String(res.path).trim();
      if (!path) return;

      // 표시용 이름은 경로 마지막 폴더명으로 자동 설정
      const baseName =
        path.split(/[/\\]/).filter(Boolean).pop() || path;

      await createWatchedFolder({ name: baseName, path });
      await refresh();
    } catch (e) {
      alert(`폴더 추가 실패: ${e.message}`);
    }
  };

  const removeFolder = async (id) => {
    try {
      await deleteWatchedFolder(id);
      await refresh();
    } catch (e) {
      alert(`폴더 삭제 실패: ${e.message}`);
    }
  };

  // ✅ 기존 코드 호환을 위해 promptAndAddFolder alias 유지
  return {
    folders,
    loading,
    error,
    refresh,

    pickAndAddFolder,
    promptAndAddFolder: pickAndAddFolder, // 🔥 alias

    removeFolder,
  };
}
